  b3_state := 'service role wrote lead_ref_code=' || coalesce(v_txt, 'NULL') || ' (read back)';
  b3_ok := v_txt = 'KQ7M2Z';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; b3_state := 'REFUSED /api/pase''s write: ' || SQLSTATE || ' ' || SQLERRM; b3_ok := false;
END;

