    INSERT INTO public.referrals (referrer_id, referral_code, status) VALUES (k_ref, k_code, 'pending');
    c1_state := 'the referrer created their own code row, as /referral does'; c1_ok := true;
  EXCEPTION WHEN OTHERS THEN
    c1_state := 'REFUSED the /referral page''s write: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
