  c1_state := 'scaffolding failed: ' || SQLERRM; c1_ok := false;
END;

-- C2: THE FORGERY CLOSED. The same user claims to have referred someone.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ref::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    INSERT INTO public.referrals (referrer_id, referred_id, referral_code, status)
    VALUES (k_ref, k_new, k_code, 'signed_up');
    c2_state := 'SUCCEEDED -- a user forged a referral of another account';
  EXCEPTION WHEN OTHERS THEN
    c2_state := SQLSTATE || ' ' || SQLERRM;
    c2_ok := SQLSTATE = '42501';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  c2_state := 'scaffolding failed: ' || SQLERRM; c2_ok := false;
END;

-- C3: POSITIVE. The server's link (linkSignupReferral): look up the code row,
-- then insert the credit, both as the service role.
BEGIN
  SET LOCAL ROLE service_role;
  SELECT referrer_id INTO v_id FROM public.referrals
   WHERE referral_code = k_code AND referred_id IS NULL LIMIT 1;
  INSERT INTO public.referrals (referrer_id, referred_id, referral_code, status, converted_at)
  VALUES (v_id, k_new, k_code, 'signed_up', now());
  RESET ROLE;
  SELECT count(*) INTO v_n FROM public.referrals WHERE referrer_id = k_ref AND referred_id = k_new;
  c3_state := 'lookup found referrer ' || CASE WHEN v_id = k_ref THEN 'correctly' ELSE 'WRONG' END
    || '; ' || v_n || ' credit row written';
  c3_ok := v_id = k_ref AND v_n = 1;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; c3_state := 'REFUSED the server''s link: ' || SQLSTATE || ' ' || SQLERRM; c3_ok := false;
END;

-- C4: a second credit for the same person is refused by the one-credit index.
