BEGIN
  DROP POLICY "Lead referral code is server only" ON public.pass_leads;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'pass_leads' AND policyname = 'Lead referral code is server only') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d1_state := SQLERRM; d1_ok := SQLERRM LIKE '215 ABORTED: policy "Lead referral code is server only"%';
END;

BEGIN
  DROP INDEX public.referrals_one_credit_per_referred;
  CREATE INDEX referrals_one_credit_per_referred ON public.referrals (referred_id);
  IF EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'referrals_one_credit_per_referred'
              AND indexdef ILIKE 'CREATE UNIQUE INDEX%') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d2_state := SQLERRM; d2_ok := SQLERRM LIKE '215 ABORTED: referrals_one_credit_per_referred is missing, not unique%';
END;

BEGIN
  DROP POLICY "Clients create only code rows" ON public.referrals;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'referrals' AND policyname = 'Clients create only code rows') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d3_state := SQLERRM; d3_ok := SQLERRM LIKE '215 ABORTED: policy "Clients create only code rows"%';
END;

-- D4: the same policy recreated PERMISSIVE, where it would be ORed away and
-- restrict nothing (CLAUDE.md: permissive policies OR together).
BEGIN
  DROP POLICY "Clients create only code rows" ON public.referrals;
  CREATE POLICY "Clients create only code rows" ON public.referrals FOR INSERT WITH CHECK (referred_id IS NULL);
  IF (SELECT permissive FROM pg_policies WHERE tablename = 'referrals' AND policyname = 'Clients create only code rows') <> 'PERMISSIVE' THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d4_state := SQLERRM; d4_ok := SQLERRM LIKE '215 ABORTED: policy "Clients create only code rows"%';
END;

-- ── PART E: the bug reverted ───────────────────────────────────────────────
-- Without 215's referrals policy, can a user forge a referral? YES is the
-- premise: the pre-existing policy admits it, and 215 is the only thing closing it.
BEGIN
  DROP POLICY "Clients create only code rows" ON public.referrals;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ref::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    INSERT INTO public.referrals (referrer_id, referred_id, referral_code, status)
    VALUES (k_ref, k_ref, k_code, 'signed_up');
    e1_state := 'without 215''s policy, a user forged a referral row'; e1_ok := true;
  EXCEPTION WHEN OTHERS THEN
    e1_state := 'without 215''s policy the forgery was STILL refused: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  RAISE EXCEPTION 'E1_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  IF SQLERRM <> 'E1_ROLLBACK' THEN e1_state := 'scaffolding failed: ' || SQLERRM; e1_ok := false; END IF;
END;

-- ── PART F: baseline ──────────────────────────────────────────────────────
SELECT count(*) INTO v_n FROM public.referrals
 WHERE referred_id IS NOT NULL AND referred_id NOT IN (k_ref, k_new);
f1_state := v_n || ' real referrals rows carry a referred_id (the one-credit index needed 0 duplicates)';
f1_ok := true;
f1_ok := NOT EXISTS (SELECT referred_id FROM public.referrals WHERE referred_id IS NOT NULL
                      GROUP BY referred_id HAVING count(*) > 1);

SELECT count(*) INTO v_n FROM public.pass_leads WHERE lead_ref_code IS NOT NULL AND slug <> k_slug;
f2_state := v_n || ' real pass leads carry a lead_ref_code (must be 0: the column is new)';
f2_ok := v_n = 0;

INSERT INTO reh_probe VALUES
  (1,  'A1 the column, two partial unique indexes, two restrictive policies', a1_state, a1_ok),
  (2,  'A2 SCAFFOLDING: two throwaway signups and a throwaway partner with a live pass', a2_state, a2_ok),
  (3,  'F3 IDENTITY: auth.uid() is NULL outside the arms', f3_state, f3_ok),
  (4,  'B1 POSITIVE: an anonymous claim with no code still works (the live form)', b1_state, b1_ok),
  (5,  'B2 an anonymous claim bringing its own lead_ref_code is refused', b2_state, b2_ok),
  (6,  'B3 POSITIVE: /api/pase''s service-role write with a code, read back', b3_state, b3_ok),
  (7,  'B4 a code outside the alphabet is refused by the shape CHECK', b4_state, b4_ok),
  (8,  'B5 a duplicate code is a 23505 on the new index (the retry path)', b5_state, b5_ok),
  (9,  'C1 POSITIVE: a user still creates their own code row (/referral)', c1_state, c1_ok),
  (10, 'C2 a user can no longer forge a referral of another account', c2_state, c2_ok),
  (11, 'C3 POSITIVE: the server''s lookup and link write the credit', c3_state, c3_ok),
  (12, 'C4 one credit per referred person', c4_state, c4_ok),
  (13, 'D0 POSITIVE: 215''s guard passes on the real end state', d0_state, d0_ok),
  (14, 'D1 guard fires when the pass_leads policy is missing', d1_state, d1_ok),
  (15, 'D2 guard fires when the one-credit index is not unique', d2_state, d2_ok),
  (16, 'D3 guard fires when the referrals policy is missing', d3_state, d3_ok),
  (17, 'D4 guard fires when the referrals policy is PERMISSIVE', d4_state, d4_ok),
  (18, 'E1 PREMISE: without 215, a user CAN forge a referral', e1_state, e1_ok),
  (19, 'F1 BASELINE: no referred person is already credited twice', f1_state, f1_ok),
  (20, 'F2 BASELINE: no real lead has a lead_ref_code yet', f2_state, f2_ok);

END $outer$;

-- The one result set for the transaction. Every row must read PASS. 20 of 20.
SELECT seq, CASE WHEN coalesce(passed, false) THEN 'PASS' ELSE 'FAIL' END AS result, check_name,
       coalesce(detail, '(probe row missing)') AS detail
FROM reh_probe ORDER BY seq;

ROLLBACK;

-- ══════════════════════════════════════════════════════════════════════════
-- PART G: nothing escaped. RUN AS ITS OWN STATEMENT, AFTER THE ROLLBACK.
-- Expected BEFORE apply: no lead_ref_code, neither index nor policy, no
-- rehearsal rows anywhere, 215 not recorded.
-- ══════════════════════════════════════════════════════════════════════════

SELECT t.seq, CASE WHEN t.passed THEN 'PASS' ELSE 'FAIL' END AS result, t.check_name, t.detail
FROM (VALUES
  (1, 'G1 pass_leads has no lead_ref_code column',
      (SELECT coalesce(string_agg(attname, ', '), '(none, as expected)') FROM pg_attribute
        WHERE attrelid = 'public.pass_leads'::regclass AND attname = 'lead_ref_code' AND NOT attisdropped),
      NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public.pass_leads'::regclass
                   AND attname = 'lead_ref_code' AND NOT attisdropped)),
  (2, 'G2 neither new index nor new policy exists',
      (SELECT count(*) FROM pg_indexes WHERE indexname IN ('pass_leads_lead_ref_code_key', 'referrals_one_credit_per_referred'))::text
      || ' indexes, '
      || (SELECT count(*) FROM pg_policies WHERE policyname IN ('Lead referral code is server only', 'Clients create only code rows'))::text
      || ' policies',
      NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname IN ('pass_leads_lead_ref_code_key', 'referrals_one_credit_per_referred'))
      AND NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname IN ('Lead referral code is server only', 'Clients create only code rows'))),
  (3, 'G3 no rehearsal account, partner, lead or referral escaped',
      (SELECT count(*) FROM auth.users WHERE email LIKE 'reh-215-%')::text || ' auth, '
      || (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh215%')::text || ' partners, '
      || (SELECT count(*) FROM public.pass_leads WHERE slug LIKE 'reh215%')::text || ' leads, '
      || (SELECT count(*) FROM public.referrals WHERE referral_code IN ('TRIBE-RH215', 'TRIBE-OTHER'))::text || ' referrals',
      (SELECT count(*) FROM auth.users WHERE email LIKE 'reh-215-%') = 0
      AND (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh215%') = 0
      AND (SELECT count(*) FROM public.pass_leads WHERE slug LIKE 'reh215%') = 0
      AND (SELECT count(*) FROM public.referrals WHERE referral_code IN ('TRIBE-RH215', 'TRIBE-OTHER')) = 0),
  (4, 'G4 the three pre-existing referrals policies are untouched',
      (SELECT string_agg(policyname, ' | ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'referrals'),
      (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'referrals') = 3),
  (5, 'G5 215 is NOT recorded as applied',
      (SELECT coalesce(string_agg(migration, ', '), '(not recorded, as expected)')
         FROM public.migrations_applied WHERE migration LIKE '215%'),
      (SELECT count(*) FROM public.migrations_applied WHERE migration LIKE '215%') = 0)
) AS t(seq, check_name, detail, passed)
ORDER BY t.seq;
